<?php
require_once APP_PATH.'/services/Calls/PhoneNormalizer.php';require_once APP_PATH.'/services/Calls/OpenRouterAnalyzer.php';require_once APP_PATH.'/services/Calls/GeminiCallAnalyzer.php';
final class CallSyncService {
 public function __construct(private PDO $db,private IntegrationConfig $config){}
 public static function contactNumber(array $c):?string{return PhoneNormalizer::canonical((string)($c['to']??''))??PhoneNormalizer::canonical((string)($c['from']??''));}
 public function run(int $pages=3,int $jobs=3):array{$synced=0;for($page=1;$page<=max(1,$pages);$page++)foreach($this->fetchCalls($page)as $call)if(!empty($call['record_url'])){$this->upsert($call);$synced++;}$processed=$this->process($jobs);return compact('synced','processed');}
 public function importLegacy(string $directory,int $pages=100,bool $dryRun=true):array{$result=['with_recording'=>0,'with_analysis'=>0,'imported'=>0,'voicemail'=>0,'invalid'=>0];for($page=1;$page<=max(1,$pages);$page++){foreach($this->fetchCalls($page)as$c){if(empty($c['record_url']))continue;$result['with_recording']++;$x=(string)($c['id']??'');$file=rtrim($directory,'/\\').DIRECTORY_SEPARATOR.hash('sha256',$x).'.json';if(!is_file($file))continue;$result['with_analysis']++;try{$raw=file_get_contents($file);$a=json_decode((string)$raw,true,512,JSON_THROW_ON_ERROR);$transcript=mb_strtolower((string)($a['transcript']??''));$a['call_outcome']=(str_contains($transcript,'caixa postal')||str_contains($transcript,'correio de voz'))?'voicemail':($a['call_outcome']??'conversation');$a=(new AnalysisNormalizer())->normalize($a,'gemini',(string)($a['provider_model']??'legado'));if($a['call_outcome']==='voicemail'){$result['voicemail']++;if(!$dryRun){$this->upsert($c);$this->db->prepare("UPDATE call_records SET outcome='voicemail',analysis_status='discarded',recording_status='discarded' WHERE provider='api4com' AND external_id=:x")->execute([':x'=>$x]);}continue;}if(!$dryRun){$this->upsert($c);$id=(int)$this->db->query("SELECT id FROM call_records WHERE provider='api4com' AND external_id=".$this->db->quote($x))->fetchColumn();$j=json_encode($a,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$q=$this->db->prepare("INSERT INTO call_analyses(call_id,analysis_version,summary,transcript,sentiment,lead_temperature,sales_stage,call_outcome,overall_score,provider,provider_model,payload,analyzed_at) VALUES(:id,:v,:s,:t,:se,:lt,:st,:o,:sc,:p,:m,:j,NOW()) ON DUPLICATE KEY UPDATE payload=VALUES(payload),summary=VALUES(summary),transcript=VALUES(transcript)");$q->execute([':id'=>$id,':v'=>$a['analysis_version'],':s'=>$a['summary'],':t'=>$a['transcript'],':se'=>$a['sentiment'],':lt'=>$a['lead_temperature'],':st'=>$a['sales_stage'],':o'=>$a['call_outcome'],':sc'=>$a['scores']['overall'],':p'=>$a['provider'],':m'=>$a['provider_model'],':j'=>$j]);$this->db->prepare("UPDATE call_records SET outcome=:o,analysis_status='completed' WHERE id=:id")->execute([':o'=>$a['call_outcome'],':id'=>$id]);$this->db->prepare("UPDATE call_processing_jobs SET status='completed',completed_at=NOW() WHERE call_id=:id AND job_type='analyze'")->execute([':id'=>$id]);}$result['imported']++;}catch(Throwable$e){$result['invalid']++;}}}return$result;}
 private function fetchCalls(int $page,array $where=[]):array{$filter=['order'=>'started_at DESC','limit'=>20];if($where)$filter['where']=$where;$url=rtrim((string)$this->config->get('api4com','base_url','https://api.api4com.com/api/v1'),'/').'/calls?'.http_build_query(['page'=>$page,'filter'=>json_encode($filter)]);$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30,CURLOPT_HTTPHEADER=>['Authorization: '.$this->config->get('api4com','token',''),'Accept: application/json']]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if(!is_string($raw)||$code<200||$code>=300)throw new RuntimeException('API4COM_SYNC_FAILED');$data=json_decode($raw,true,512,JSON_THROW_ON_ERROR);return is_array($data['data']??null)?$data['data']:[];}
 private function upsert(array $c):void{$x=trim((string)($c['id']??''));if($x===''||!preg_match('/^[A-Za-z0-9._:-]{1,160}$/',$x))return;$phone=self::contactNumber($c);[$lead,$link]=$this->matchLead($phone);$email=strtolower(trim((string)($c['email']??'')));$uid=null;if($email!==''){$q=$this->db->prepare('SELECT id FROM users WHERE LOWER(email)=:e AND active=1 LIMIT 1');$q->execute([':e'=>$email]);$uid=$q->fetchColumn()?:null;}$q=$this->db->prepare("INSERT INTO call_records(provider,external_id,lead_id,user_id,agent_external_key,contact_phone,normalized_phone,direction,started_at,ended_at,duration,hangup_cause,call_price,link_status,recording_url_hash) VALUES('api4com',:x,:l,:u,:a,:p,:n,'unknown',:s,:e,:du,:h,:price,:link,:rh) ON DUPLICATE KEY UPDATE lead_id=COALESCE(lead_id,VALUES(lead_id)),user_id=COALESCE(user_id,VALUES(user_id)),link_status=IF(link_status='manual',link_status,VALUES(link_status)),updated_at=NOW()");$q->execute([':x'=>$x,':l'=>$lead,':u'=>$uid,':a'=>$email?:null,':p'=>$phone,':n'=>$phone,':s'=>$this->date($c['started_at']??null),':e'=>$this->date($c['ended_at']??null),':du'=>max(0,(int)($c['duration']??0)),':h'=>mb_substr((string)($c['hangup_cause']??''),0,120),':price'=>is_numeric($c['call_price']??null)?$c['call_price']:null,':link'=>$link,':rh'=>hash('sha256',(string)$c['record_url'])]);$id=(int)$this->db->query("SELECT id FROM call_records WHERE provider='api4com' AND external_id=".$this->db->quote($x))->fetchColumn();$this->db->prepare("INSERT IGNORE INTO call_processing_jobs(call_id,job_type,status) VALUES(:id,'analyze','pending')")->execute([':id'=>$id]);}
 private function matchLead(?string $phone):array{if(!$phone)return[null,'unmatched'];$ids=[];foreach($this->db->query('SELECT id,phone,whatsapp FROM leads')->fetchAll()as$r)if(PhoneNormalizer::canonical($r['phone']??null)===$phone||PhoneNormalizer::canonical($r['whatsapp']??null)===$phone)$ids[]=(int)$r['id'];$ids=array_values(array_unique($ids));return count($ids)===1?[$ids[0],'matched']:[null,count($ids)>1?'ambiguous':'unmatched'];}
 private function process(int $limit):int{$rows=$this->db->query("SELECT j.id job_id,c.* FROM call_processing_jobs j JOIN call_records c ON c.id=j.call_id WHERE j.status IN('pending','failed') AND j.available_at<=NOW() ORDER BY j.id LIMIT ".max(1,min(10,$limit)))->fetchAll();$done=0;foreach($rows as$c){try{$this->processOne($c);$done++;}catch(Throwable$e){$q=$this->db->prepare("UPDATE call_processing_jobs SET status='failed',attempts=attempts+1,available_at=DATE_ADD(NOW(),INTERVAL 15 MINUTE),last_error_code=:e WHERE id=:id");$q->execute([':e'=>preg_replace('/[^A-Z0-9_]/','',strtoupper(substr($e->getMessage(),0,80))),':id'=>$c['job_id']]);}}return$done;}
 private function processOne(array$c):void{$remote=$this->fetchCalls(1,['id'=>$c['external_id']])[0]??[];$url=(string)($remote['record_url']??'');$host=strtolower((string)parse_url($url,PHP_URL_HOST));if($url===''||!($host==='api4com.com'||str_ends_with($host,'.api4com.com')))throw new RuntimeException('INVALID_RECORDING_URL');if(!is_dir(STORAGE_PATH.'/tmp'))mkdir(STORAGE_PATH.'/tmp',0775,true);$tmp=tempnam(STORAGE_PATH.'/tmp','call-');$fh=fopen($tmp,'wb');$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_FILE=>$fh,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_TIMEOUT=>120]);$ok=curl_exec($ch);$mime=(string)(curl_getinfo($ch,CURLINFO_CONTENT_TYPE)?:'audio/mpeg');curl_close($ch);fclose($fh);if(!$ok||filesize($tmp)===0){@unlink($tmp);throw new RuntimeException('RECORDING_DOWNLOAD_FAILED');}try{$p=$this->db->query("SELECT * FROM ai_provider_configs WHERE is_active=1 AND enabled=1 LIMIT 1")->fetch();if(!$p)throw new RuntimeException('AI_NOT_CONFIGURED');$key=(string)$this->config->get($p['provider'],'api_key','');$ai=$p['provider']==='openrouter'?new OpenRouterAnalyzer($p['base_url'],$key,$p['model']):new GeminiCallAnalyzer($p['base_url'],$key,$p['model']);$a=$ai->analyze($tmp,$mime,$remote);if($a['call_outcome']==='voicemail'){$this->db->prepare("UPDATE call_records SET outcome='voicemail',analysis_status='discarded',recording_status='discarded' WHERE id=:id")->execute([':id'=>$c['id']]);@unlink($tmp);}else{$dir=STORAGE_PATH.'/calls/'.date('Y/m');if(!is_dir($dir))mkdir($dir,0775,true);$name=bin2hex(random_bytes(20)).'.audio';$dest=$dir.'/'.$name;rename($tmp,$dest);$json=json_encode($a,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$q=$this->db->prepare("INSERT INTO call_analyses(call_id,analysis_version,summary,transcript,sentiment,lead_temperature,sales_stage,call_outcome,overall_score,provider,provider_model,payload,analyzed_at) VALUES(:id,:v,:s,:t,:se,:lt,:st,:o,:sc,:p,:m,:j,NOW()) ON DUPLICATE KEY UPDATE analysis_version=VALUES(analysis_version),summary=VALUES(summary),transcript=VALUES(transcript),payload=VALUES(payload),analyzed_at=NOW()");$q->execute([':id'=>$c['id'],':v'=>$a['analysis_version'],':s'=>$a['summary'],':t'=>$a['transcript'],':se'=>$a['sentiment'],':lt'=>$a['lead_temperature'],':st'=>$a['sales_stage'],':o'=>$a['call_outcome'],':sc'=>$a['scores']['overall'],':p'=>$a['provider'],':m'=>$a['provider_model'],':j'=>$json]);$days=(int)$this->setting('calls_audio_retention_days','365');$exp=$days===0?null:date('Y-m-d H:i:s',time()+$days*86400);$this->db->prepare("UPDATE call_records SET outcome=:o,analysis_status='completed',recording_status='stored',recording_path=:path,recording_mime=:mime,recording_size=:size,recording_checksum=:hash,recording_expires_at=:exp WHERE id=:id")->execute([':o'=>$a['call_outcome'],':path'=>date('Y/m').'/'.$name,':mime'=>$mime,':size'=>filesize($dest),':hash'=>hash_file('sha256',$dest),':exp'=>$exp,':id'=>$c['id']]);$this->history((int)$c['id']);}}finally{if(is_file($tmp))@unlink($tmp);}$this->db->prepare("UPDATE call_processing_jobs SET status='completed',completed_at=NOW() WHERE id=:id")->execute([':id'=>$c['job_id']]);}
 private function history(int$id):void{$c=$this->db->query('SELECT * FROM call_records WHERE id='.$id)->fetch();if(!$c||!$c['lead_id']||$c['lead_history_id'])return;$this->db->prepare("INSERT INTO lead_history(lead_id,user_id,type,description,created_at) VALUES(:l,:u,'ligacao','Ligação sincronizada e analisada automaticamente.',COALESCE(:at,NOW()))")->execute([':l'=>$c['lead_id'],':u'=>$c['user_id'],':at'=>$c['started_at']]);$h=(int)$this->db->lastInsertId();$this->db->prepare('UPDATE call_records SET lead_history_id=:h WHERE id=:id AND lead_history_id IS NULL')->execute([':h'=>$h,':id'=>$id]);$this->db->prepare('UPDATE leads SET last_contact_at=CASE WHEN last_contact_at IS NULL OR last_contact_at<:a THEN :b ELSE last_contact_at END WHERE id=:id')->execute([':a'=>$c['started_at'],':b'=>$c['started_at'],':id'=>$c['lead_id']]);}
 private function setting(string$k,string$d):string{$s=$this->db->prepare('SELECT value FROM settings WHERE `key`=:k');$s->execute([':k'=>$k]);$v=$s->fetchColumn();return$v===false?$d:(string)$v;}private function date(mixed$v):?string{if(!$v)return null;$t=strtotime((string)$v);return$t?date('Y-m-d H:i:s',$t):null;}
}
